using System;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using UnityEngine;
namespace NailAtelier {
// Small JSON normalizer handles the web editor's [u,v] arrays without an extra package.
public static class AtelierImport {
 public static SaveData Merge(Catalog catalog,SaveData current,string json){var map=MiniJson.Parse(json) as Dictionary<string,object>;if(map==null)throw new Exception("需要 JSON 对象");var d=Rules.Copy(current);
  if(map.ContainsKey("session")||map.ContainsKey("album")){NormalizeDesigns(map);d=Rules.ReadSave(MiniJson.Write(map));}
  else if(map.ContainsKey("nails")){NormalizeDesigns(map);var design=JsonUtility.FromJson<Design>(MiniJson.Write(map));Rules.ValidateDesign(design);d.free=design;var old=d.album.FirstOrDefault(a=>a.id==design.id);if(old!=null){old.design=Rules.Copy(design);old.name=design.name;}else d.album.Add(new AlbumEntry{id=design.id,name=design.name,design=Rules.Copy(design)});}
  else if(map.ContainsKey("receipts")){map["version"]=1;var wallet=JsonUtility.FromJson<SaveData>(MiniJson.Write(map));d.receipts=wallet.receipts??new List<Receipt>();d.purchases=wallet.purchases??new List<Purchase>();d.studio=wallet.studio??new Studio();}
  else if(map.ContainsKey("client")&&map.ContainsKey("plan")){
   var id=map["client"] as string;var c=catalog.Find(id);if(c==null)throw new Exception("未知顾客");NormalizeDesigns(map["plan"]);var s=Rules.Create(c);s.plan=JsonUtility.FromJson<Design>(MiniJson.Write(map["plan"]));s.id=map.ContainsKey("id")?(string)map["id"]:Rules.Id();s.phase=(string)map["phase"];s.step=Convert.ToInt32(map["step"]);if(map.ContainsKey("returnVisit"))s.returnVisit=Convert.ToInt32(map["returnVisit"]);if(map.ContainsKey("consultation"))s.consultation=((List<object>)map["consultation"]).Cast<string>().ToList();var work=(List<object>)map["work"];if(work.Count!=10)throw new Exception("需要十指施工记录");for(int i=0;i<10;i++){var w=(Dictionary<string,object>)work[i];s.work[i].done=((List<object>)w["done"]).Cast<string>().ToList();}d.session=s;
  }else throw new Exception("不是作品、服务或工作室备份");Rules.Validate(catalog,d);return d;
 }
 static void NormalizeDesigns(object node){var m=node as Dictionary<string,object>;if(m!=null){if(m.ContainsKey("nails")){var nails=m["nails"] as List<object>;if(nails==null||nails.Count!=10)throw new Exception("需要十指作品");foreach(var raw in nails){var n=raw as Dictionary<string,object>;if(n==null)throw new Exception("甲面无效");if(n.ContainsKey("gradient")&&n["gradient"] is Dictionary<string,object> g&&!g.ContainsKey("enabled"))g["enabled"]=true;var defaults=MiniJson.Parse(JsonUtility.ToJson(new Polish())) as Dictionary<string,object>;Dictionary<string,object> p=n.ContainsKey("polish")?n["polish"] as Dictionary<string,object>:null;if(p!=null)foreach(var kv in p)defaults[kv.Key]=kv.Value;if(!n.ContainsKey("polish")&&(string)n["finish"]=="metal")defaults["chrome"]=1;n["polish"]=defaults;object strokes;if(n.TryGetValue("strokes",out strokes)&&strokes is List<object>)foreach(var rawStroke in (List<object>)strokes){var s=(Dictionary<string,object>)rawStroke;var points=(List<object>)s["points"];for(int i=0;i<points.Count;i++)if(points[i] is List<object>){var uv=(List<object>)points[i];if(uv.Count!=2)throw new Exception("笔迹坐标无效");points[i]=new Dictionary<string,object>{{"u",uv[0]},{"v",uv[1]}};}}}}foreach(var v in m.Values.ToArray())NormalizeDesigns(v);}else if(node is List<object>)foreach(var x in (List<object>)node)NormalizeDesigns(x);}
}
public static class MiniJson {
 public static object Parse(string s){var p=new Parser(s);var v=p.Value();p.White();if(!p.End)throw new FormatException("JSON 尾部有多余字符");return v;}
 public static string Write(object v){var b=new StringBuilder();WriteValue(b,v);return b.ToString();}
 static void WriteValue(StringBuilder b,object v){if(v==null){b.Append("null");return;}if(v is string){b.Append('"');foreach(char c in (string)v){switch(c){case '"':b.Append("\\\"");break;case '\\':b.Append("\\\\");break;case '\n':b.Append("\\n");break;case '\r':b.Append("\\r");break;case '\t':b.Append("\\t");break;default:if(c<32)b.Append("\\u"+((int)c).ToString("x4"));else b.Append(c);break;}}b.Append('"');}else if(v is Dictionary<string,object>){b.Append('{');bool first=true;foreach(var x in (Dictionary<string,object>)v){if(!first)b.Append(',');first=false;WriteValue(b,x.Key);b.Append(':');WriteValue(b,x.Value);}b.Append('}');}else if(v is List<object>){b.Append('[');bool first=true;foreach(var x in (List<object>)v){if(!first)b.Append(',');first=false;WriteValue(b,x);}b.Append(']');}else if(v is bool)b.Append((bool)v?"true":"false");else b.Append(Convert.ToString(v,CultureInfo.InvariantCulture));}
 class Parser {readonly string s;int p,depth;public Parser(string t){s=t;}public bool End=>p==s.Length;public void White(){while(p<s.Length&&char.IsWhiteSpace(s[p]))p++;}char Take(){if(p>=s.Length)throw new FormatException("JSON 未结束");return s[p++];}
 public object Value(){White();if(++depth>120)throw new FormatException("JSON 嵌套过深");object v;char c=p<s.Length?s[p]:'\0';if(c=='{'){p++;var d=new Dictionary<string,object>();White();if(p<s.Length&&s[p]=='}'){p++;v=d;}else{while(true){White();string key=String();White();if(Take()!=':')throw new FormatException();if(d.ContainsKey(key))throw new FormatException("JSON 字段重复");d[key]=Value();White();char n=Take();if(n=='}')break;if(n!=',')throw new FormatException();}v=d;}}else if(c=='['){p++;var a=new List<object>();White();if(p<s.Length&&s[p]==']')p++;else while(true){a.Add(Value());White();char n=Take();if(n==']')break;if(n!=',')throw new FormatException();}v=a;}else if(c=='"')v=String();else if(s.Substring(p).StartsWith("true")){p+=4;v=true;}else if(s.Substring(p).StartsWith("false")){p+=5;v=false;}else if(s.Substring(p).StartsWith("null")){p+=4;v=null;}else{int start=p;while(p<s.Length&&"0123456789+-.eE".IndexOf(s[p])>=0)p++;if(start==p)throw new FormatException("JSON 数值无效");double num;if(!double.TryParse(s.Substring(start,p-start),NumberStyles.Float,CultureInfo.InvariantCulture,out num)||double.IsNaN(num)||double.IsInfinity(num))throw new FormatException("数值无效");v=num;}depth--;return v;}
 string String(){if(Take()!='"')throw new FormatException();var b=new StringBuilder();while(true){char c=Take();if(c=='"')return b.ToString();if(c=='\\'){char e=Take();switch(e){case '"':b.Append('"');break;case '\\':b.Append('\\');break;case '/':b.Append('/');break;case 'n':b.Append('\n');break;case 'r':b.Append('\r');break;case 't':b.Append('\t');break;case 'b':b.Append('\b');break;case 'f':b.Append('\f');break;case 'u':if(p+4>s.Length)throw new FormatException();b.Append((char)int.Parse(s.Substring(p,4),NumberStyles.HexNumber));p+=4;break;default:throw new FormatException();}}else{if(c<32)throw new FormatException();b.Append(c);}}}
 }
}
}
